contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function test(address other, uint256 amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(other != address(this));
        require(address(this).balance >= amount);
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        assert(c.getBalance(other) == 0);
    }
    receive() external payable {}
    fallback() external payable {}
}

